import{_ as a,o as n,c as e,a0 as l}from"./chunks/framework.DqMqoJl9.js";const b=JSON.parse('{"title":"官方文档 - Rules","description":"","frontmatter":{},"headers":[],"relativePath":"cursor/docs-rules.md","filePath":"cursor/docs-rules.md","lastUpdated":1791573371000}'),p={name:"cursor/docs-rules.md"};function r(t,s,i,o,c,d){return n(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="官方文档-rules" tabindex="-1">官方文档 - Rules <a class="header-anchor" href="#官方文档-rules" aria-label="Permalink to &quot;官方文档 - Rules&quot;">​</a></h1><p>Cursor 支持四种类型的 Rules:</p><ul><li>Project Rules: 存储在 <code>.cursor/rules</code> 中，受版本控制且仅作用于你的代码库</li><li>User Rules: 在你的 Cursor 环境中全局生效，供 Agent (聊天) 使用</li><li>Team Rules: 在仪表盘中集中管理的团队级规则，适用于 Team 和 Enterprise 方案</li><li>AGENTS.md: 以 Markdown 格式编写的 Agent 指令，是 <code>.cursor/rules</code> 的简化替代方案</li></ul><h2 id="project-rules" tabindex="-1">Project Rules <a class="header-anchor" href="#project-rules" aria-label="Permalink to &quot;Project Rules&quot;">​</a></h2><p>项目规则存放在 <code>.cursor/rules</code> 目录中的 Markdown 文件里，并纳入版本控制。它们可以通过路径模式限定作用范围、手动触发，或按相关性自动应用</p><p><strong>project rules 作用：</strong></p><ul><li>固化与你代码库相关的领域知识</li><li>自动化项目特定的工作流或模板</li><li>统一风格或架构决策</li></ul><p><strong>rules 文件结构：</strong></p><p>每条规则对应一个 Markdown 文件，文件名可自定义。Cursor 支持 <code>.md</code> 和 <code>.mdc</code> 扩展名。使用带有 frontmatter 的 <code>.mdc</code> 文件来指定 <code>description</code> 和 <code>globs</code>，以便更精细地控制规则的生效条件</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>.cursor/rules/</span></span>
<span class="line"><span>  react-patterns.mdc       # 带有前置元数据的规则（description, globs）</span></span>
<span class="line"><span>  api-guidelines.md        # 简单的 markdown 规则</span></span>
<span class="line"><span>  frontend/                # 在文件夹中组织规则</span></span>
<span class="line"><span>    components.md</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>rules 结构：</strong></p><p>每条规则都是一个带有 frontmatter 元数据和内容的 markdown 文件。通过类型下拉菜单控制规则的应用方式，该菜单会更改 <code>description</code>、<code>globs</code>、<code>alwaysApply</code> 属性</p><table tabindex="0"><thead><tr><th>rules 类型</th><th>描述</th></tr></thead><tbody><tr><td>Always Apply</td><td>应用于每个聊天会话</td></tr><tr><td>Apply Intelligently</td><td>当 Agent 根据描述判断其相关时应用</td></tr><tr><td>Apply to Specific Files</td><td>当文件匹配指定模式时</td></tr><tr><td>Apply Manually</td><td>当在聊天中@提及（例如， <code>@my-rule</code>）</td></tr></tbody></table><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>globs:</span></span>
<span class="line"><span>alwaysApply: false</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Use our internal RPC pattern when defining services</span></span>
<span class="line"><span>- Always use snake_case for service names.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@service-template.ts</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>创建 rules：</strong></p><p>有两种方式可以创建规则</p><ul><li>在对话中使用 <code>/create-rule</code>：在 Agent 中输入 <code>/create-rule</code>，然后描述你的需求。Agent 会生成带有正确 frontmatter 的规则文件，并将其保存到 <code>.cursor/rules</code></li><li>在设置中创建：打开 <code>Cursor Settings &gt; Rules, Commands</code>，然后点击 <code>+ Add Rule</code>。这会在 <code>.cursor/rules</code> 中创建一个新的规则文件。在设置中可以查看所有规则及其状态</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><p>好的规则应当聚焦、可操作且范围明确</p><ul><li>将规则控制在 500 行以内</li><li>将大型规则拆分为多个可组合的规则</li><li>提供具体示例或引用相关文件</li><li>避免模糊的指导，像撰写清晰的内部文档那样来写规则</li><li>在聊天中重复提示时复用规则</li><li>引用文件而不是复制其内容——这样可以让规则更简短，并避免在代码变更后规则变得陈旧</li></ul><p><strong>rules 中应避免的内容：</strong></p><ul><li>整份照搬风格指南：请改用 <code>linter</code>。Agent 已经了解常见的风格规范</li><li>把每一个可能的命令都写进文档：Agent 了解常用工具，比如 <code>npm</code>、<code>git</code> 和 <code>pytest</code></li><li>为极少出现的边缘情况添加说明：让规则只聚焦在你经常使用的模式上</li><li>重复你代码库中已有的内容：引用规范示例，而不是复制代码</li></ul><blockquote><p>从简单开始。只有在你发现 Agent 反复犯同样的错误时才添加规则。在你真正理解自己的模式之前，不要过度优化</p></blockquote><h2 id="rules-文件格式" tabindex="-1">rules 文件格式 <a class="header-anchor" href="#rules-文件格式" aria-label="Permalink to &quot;rules 文件格式&quot;">​</a></h2><p>每条规则都是一个包含 frontmatter 元数据和正文内容的 Markdown 文件。frontmatter 元数据用于控制规则的应用方式，正文则定义规则本身</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>description: &quot;This rule provides standards for frontend components and API validation&quot;</span></span>
<span class="line"><span>alwaysApply: false</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>...rest of the rule content</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>如果 <code>alwaysApply</code> 为 <code>true</code>，该规则将应用于每个聊天会话。否则，规则的描述将呈现给 Cursor Agent，由其决定是否应用该规则</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><p>todo</p><h2 id="team-rules" tabindex="-1">Team Rules <a class="header-anchor" href="#team-rules" aria-label="Permalink to &quot;Team Rules&quot;">​</a></h2><p>todo</p><h2 id="导入-rules" tabindex="-1">导入 Rules <a class="header-anchor" href="#导入-rules" aria-label="Permalink to &quot;导入 Rules&quot;">​</a></h2><p>远程导入</p><p>todo</p><h2 id="agents-md" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agents-md" aria-label="Permalink to &quot;AGENTS.md&quot;">​</a></h2><p><code>AGENTS.md</code> 是一个用于定义 <code>agent</code> 指令的简单 <code>markdown</code> 文件。将它放在项目根目录中，可作为 <code>.cursor/rules</code> 的一种替代方式，适用于简单直接的用例</p><p>与 Project Rules 不同，<code>AGENTS.md</code> 是不带元数据或复杂配置的纯 markdown 文件。对于只需要简单、易读指令且不想引入结构化规则开销的项目来说，它非常合适</p><p>Cursor 支持在项目根目录和子目录中使用 <code>AGENTS.md</code></p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span># Project Instructions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Code Style</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Use TypeScript for all new files</span></span>
<span class="line"><span>- Prefer functional components in React</span></span>
<span class="line"><span>- Use snake_case for database columns</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Architecture</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- Follow the repository pattern</span></span>
<span class="line"><span>- Keep business logic in service layers</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h2 id="user-rules" tabindex="-1">User Rules <a class="header-anchor" href="#user-rules" aria-label="Permalink to &quot;User Rules&quot;">​</a></h2><p>User Rules 是在 Cursor 设置 → 规则中定义的全局偏好设置，适用于所有项目。它们由代理（聊天）使用，非常适合设置首选的沟通风格或编码规范：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>Please reply in a concise style. Avoid unnecessary repetition or filler language.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>`,42)])])}const m=a(p,[["render",r]]);export{b as __pageData,m as default};
